-- One AI replay video per game, generated by the web server through the Gemini API (Veo).
-- Clients never touch this table or the bucket directly: /api/replay-video checks that the
-- caller can see the game, writes rows with the service role and returns the public video URL.

create table if not exists public.replay_videos (
  game_uuid text primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  status text not null check (status in ('generating', 'ready', 'failed')),
  operation_name text,
  prompt text,
  video_url text,
  error text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.replay_videos enable row level security;
revoke all on public.replay_videos from anon, authenticated;

insert into storage.buckets (id, name, public)
values ('replay-videos', 'replay-videos', true)
on conflict (id) do nothing;
